    static SessionClosure yes(Result frame){Result old=ContextUniversalFrozenConstraints.closeSignedCompounds(frame.input,frame.common,frame.pool,frame.exchange,frame.compounds,16,16,512,256,WORK);SessionClosure s=close(frame,16,16,512,WORK,4096);Result n=s.result;require(old.closed&&n.closed&&s.metrics.entries==0,n.reason);require(n.input==old.input&&n.common==old.common&&n.pool==old.pool&&n.exchange==old.exchange&&n.compounds==old.compounds&&n.groupedBase==null&&n.groupedInputs.isEmpty(),"same actual input and ordinary manifest");require(n.xRefuted==old.xRefuted&&n.foreignRefuted==old.foreignRefuted&&n.rounds==old.rounds&&n.obligations==old.obligations&&n.signedUnits==old.signedUnits&&n.applications==old.applications&&n.signedApplications==old.signedApplications&&n.symbolicHeads==old.symbolicHeads&&n.groundedMixed==old.groundedMixed&&n.instantiatedUnits==old.instantiatedUnits,"same refutation/mode/round/semantic-obligation inventory");require(ContextUniversalGroupedLocalRounds.sameContents(old,n,ContextGroundProductionRounds.budget(WORK)),"ALL exact clause/Source/depth minima equal ordinary kernel");ContextUniversalFrozenConstraints.check(n,16,ContextGroundProductionRounds.budget(WORK));try(ContextUniversalValidationSession.Scope audit=ContextUniversalValidationSession.open(WORK,4096)){ContextUniversalFrozenConstraints.checkSaturation(n,16,audit.work);}++checks;return s;}
